import itertools
import random

def check_k(d, Q_coeffs, max_k):
    # f(x) = -x^d + Q(x)
    def f(x):
        res = -(x**d)
        for i, coeff in enumerate(Q_coeffs):
            res += coeff * (x**i)
        return res

    # Try to find k in 1..max_k and k+1 distinct integers a_1..a_{k+1}
    # such that f(a_{k+1}) = sum(f(a_1)..f(a_k))
    # This is hard to search for all integers.
    # Let's search in a small range.
    for k in range(1, max_k + 1):
        # Search for k+1 distinct integers in range [-M, M]
        M = 15
        for a in itertools.product(range(-M, M + 1), repeat=k+1):
            if len(set(a)) == k+1:
                if f(a[k]) == sum(f(a[i]) for i in range(k)):
                    return k
    return None

