def solve():
    # f(x) = -x^3 + 2x
    def f(x):
        return -x**3 + 2*x

    # Check k=2
    for a1 in range(-10, 10):
        for a2 in range(-10, 10):
            if a1 == a2: continue
            target = f(a1) + f(a2)
            # We need f(a3) = target
            # -a3^3 + 2a3 = target
            # a3^3 - 2a3 + target = 0
            # Let's check for integer roots of a3^3 - 2a3 + target = 0
            # The roots must be divisors of target.
            if target == 0:
                # a3^3 - 2a3 = 0 => a3(a3^2 - 2) = 0 => a3 = 0.
                # But a1, a2, a3 must be distinct.
                # If a1, a2 != 0, then a3=0 is a solution.
                if a1 != 0 and a2 != 0:
                    return "k=2 works"
            else:
                # Check divisors of target
                for a3 in range(-abs(target), abs(target) + 1):
                    if a3 == a1 or a3 == a2: continue
                    if f(a3) == target:
                        return f"k=2 works for a1={a1}, a2={a2}, a3={a3}"

    # Check k=3
    for a1 in range(-10, 10):
        for a2 in range(-10, 10):
            if a1 == a2: continue
            for a3 in range(-10, 10):
                if a3 == a1 or a3 == a2: continue
                target = f(a1) + f(a2) + f(a3)
                if target == 0:
                    # a4^3 - 2a4 = 0 => a4 = 0
                    if a1 != 0 and a2 != 0 and a3 != 0:
                        return f"k=3 works for a1={a1}, a2={a2}, a3={a3}, a4=0"
                else:
                    # target = f(a4) = -a4^3 + 2a4
                    for a4 in range(-10, 10):
                        if a4 == a1 or a4 == a2 or a4 == a3: continue
                        if f(a4) == target:
                            return f"k=3 works for a1={a1}, a2={a2}, a3={a3}, a4={a4}"
    return "No solution found for f(x) = -x^3 + 2x"

print(solve())

